/// Is `root` an OS-created, single-use health-check sandbox (`scheduler::sandbox::Sandbox::create`: `<project>/
/// .governance-runtime/health/sandboxes/<purpose>-<uuid>`, a byte copy of the repository under a fresh path every
/// run, removed when dropped)?
///
/// **P2-AR-0091 (AR90-C3), hardened; P2-AR-0093 (AR92-C2), corrected; P2-AR-0095 (AR94-C1), corrected again;
/// P2-AR-0096, replaced.** The original check was a pure name shape (AR90-C3's fix); P2-AR-0093 added an
/// OS-written marker FILE keyed by the path alone; P2-AR-0095 bound that marker to the sandbox directory's own
/// `(device, inode)` after AR94-C1 proved a path-keyed marker is a capability that survives its own creator's
/// death (SIGKILL before `Drop`), letting an attacker leak one in a project of their own and reuse it, at their
/// own leisure, on a substituted victim directory.
///
/// **P2-HO-0060 §4 (owner-approved 5C Option B).** The object-identity mechanism closed AR94-C1 but was itself
/// found to be exactly the pattern OD-P2-08/OD-P2-09 now forbid: a mechanism kept alive only to guard the
/// PREVIOUS mechanism, plus a GC sweep kept alive only to bound the growth the object-identity design made
/// unavoidable. The approved replacement is simpler and closes the same reproduction differently: the exemption
/// now authenticates the CREATOR's own liveness, not the directory object.
///
/// ```text
/// live OS-created sandbox          -> exemption may be valid
/// creating/owning process dies     -> exemption is no longer authoritative -> fail closed -> cleanup/rebuild
/// ```
///
/// [`record_sandbox_root`] captures the CREATING process's own `(pid, start_time)` — read from `/proc`, never a
/// value any child process is handed (OD-P2-09 §4: "no environment variable may carry authority") — at the moment
/// [`Sandbox::create`] runs. [`creator_is_alive`] re-reads that same pid's CURRENT start time and refuses unless
/// it still matches: `starttime` is a value the kernel assigns once, at that pid's own creation, and a LATER
/// process the kernel eventually reuses the same pid for gets its OWN, different `starttime`, so `(pid,
/// starttime)` names one specific process, never a spelling the OS might hand to two different processes across
/// their lifetimes — the same "resolve the object, not a name" principle OD-P2-08 §3 already accepts for
/// execution, applied here to a *process* rather than a file.
///
/// AR94-C1's own reproduction (SIGKILL the creator, then substitute at leisure, with no time pressure at all) is
/// closed by construction: the instant the creator dies, `creator_is_alive` fails for every reader, permanently —
/// there is no window during which a leaked, creator-dead marker still grants anything, so nothing needs to sweep
/// it (the GC this replaced existed only because the OLD design's markers could otherwise leak *validly* forever).
/// `skills.rs::execute_check` holds its `Sandbox` alive across every child `gov` call it spawns (`run_gov`) for
/// exactly this reason: the creator is alive for every PRODUCTION read, cross-process, by construction — never
/// post-mortem.
///
/// **Named, not fixed: a liveness check has a different residual than an object-identity check, and this is
/// disclosed rather than silently traded away.** Unlike the deleted `(device, inode)` binding, this does not
/// authenticate that the directory AT `root` is the SAME object the OS created — only that root's PATH still has
/// a live, matching creator recorded for it. An attacker who is ALSO the creator (their own donor project, their
/// own health check) controls their own process's lifetime; while it remains genuinely alive and running (doing
/// real work, as production usage always has it), the marker is, correctly, valid — the same live-creator window
/// production reads rely on. Closing that residual further (e.g. binding to the object as well) would be exactly
/// the "add a mechanism to guard a mechanism" pattern this delta exists to stop; it is named here for Review 8
/// rather than quietly re-added.
///
/// The shape check is kept as a first, cheap filter (belt and suspenders: it costs nothing and narrows what needs
/// a marker read and a `/proc` lookup), but it does not decide anything by itself — [`creator_is_alive`] must
/// also hold.
///
/// [`Sandbox::create`]: crate::scheduler::sandbox::Sandbox::create
fn is_health_sandbox_root(state_root: &Path, root: &Path) -> bool {
    let comps: Vec<std::ffi::OsString> = root
        .components()
        .map(|c| c.as_os_str().to_owned())
        .collect();
    let shaped = comps.len() >= 4
        && comps[comps.len() - 2] == std::ffi::OsStr::new("sandboxes")
        && comps[comps.len() - 3] == std::ffi::OsStr::new("health")
        && comps[comps.len() - 4] == std::ffi::OsStr::new(crate::RUNTIME_DIR);
    if !shaped {
        return false;
    }
    let Some(rec) = read_sandbox_record(state_root, root) else {
        return false;
    };
    creator_is_alive(&rec)
}

/// **P2-AR-0096.** `/proc/<pid>/stat`'s own `starttime` field (clock ticks since boot) for `pid` — Linux only
/// (this profile: OD-P2-09 §7, "owner-controlled WSL/Linux machine"); `None` on every other target, and on Linux
/// whenever `pid` does not currently exist (no such process). Field 2 (`comm`) is parenthesised and may itself
/// contain spaces or parentheses (a process may rename itself arbitrarily), so this skips past the LAST `)`
/// rather than splitting naively, exactly like every correct `/proc/[pid]/stat` reader must; `starttime` is field
/// 22, i.e. index 19 counting from field 3 (`state`), the first field after that `)`.
#[cfg(target_os = "linux")]
fn process_start_time(pid: u32) -> Option<u64> {
    let raw = std::fs::read_to_string(format!("/proc/{pid}/stat")).ok()?;
    let after = raw.rsplit_once(')')?.1;
    after.split_whitespace().nth(19)?.parse().ok()
}
#[cfg(not(target_os = "linux"))]
fn process_start_time(_pid: u32) -> Option<u64> {
    None
}

/// Where [`Sandbox::create`] records that `root` (already canonicalised by every caller) is a genuine, OS-created
/// sandbox — a plain marker file keyed the same way [`floor_anchor_key`] keys a checkout's own anchor, under the
/// SAME protected `state_root`, so writing it needs the same privilege reaching `adoption-floors/` already needs.
/// Not sealed (T2 or otherwise): the marker asserts nothing about the CONTENT at `root`, only that the OS itself
/// created this exact object, which its location outside every project already establishes (OD-P2-08 §2 — the
/// same reasoning [`FloorIdentity`]'s own doc gives for why its anchor is not T2-sealed either).
///
/// [`Sandbox::create`]: crate::scheduler::sandbox::Sandbox::create
fn sandbox_record_path(state_root: &Path, root: &Path) -> PathBuf {
    state_root
        .join("health-sandboxes")
        .join(crate::util::sha256_hex(
            root.to_string_lossy().as_bytes(),
        ))
}

struct SandboxRecord {
    creator_pid: u32,
    creator_start_time: u64,
}

/// Parse one marker file's already-read JSON. `None` for an unparseable or pre-P2-AR-0096 marker (one written
/// before the `creator_pid`/`creator_start_time` fields existed, i.e. still shaped as `dev`/`ino`) — a leftover
/// old-shape marker must not silently keep granting the exemption once this repair lands, so it is treated as
/// unreadable, never as a match.
fn parse_sandbox_record(v: &Value) -> Option<SandboxRecord> {
    Some(SandboxRecord {
        creator_pid: v.get("creator_pid")?.as_u64()?.try_into().ok()?,
        creator_start_time: v.get("creator_start_time")?.as_u64()?,
    })
}

/// Read and parse the marker [`record_sandbox_root`] wrote for `root`, if any.
fn read_sandbox_record(state_root: &Path, root: &Path) -> Option<SandboxRecord> {
    let v = crate::util::read_json(&sandbox_record_path(state_root, root)).ok()?;
    parse_sandbox_record(&v)
}

/// Is the process that created this sandbox still the one running under `rec.creator_pid` — i.e. still alive,
/// never a later, unrelated process the OS happened to reuse that pid for? The one predicate
/// [`is_health_sandbox_root`] refuses on if it does not hold.
fn creator_is_alive(rec: &SandboxRecord) -> bool {
    process_start_time(rec.creator_pid) == Some(rec.creator_start_time)
}

/// Record that `canonical_root` (already canonicalised by the caller) is a genuine OS-created health sandbox, so
/// [`is_health_sandbox_root`] grants it the bootstrap exemption for as long as the CREATING process (this one,
/// `std::process::id()`, at the moment this runs — `Sandbox::create` calls this synchronously in its own
/// process) stays alive. Called once, from [`Sandbox::create`] itself, before any project code can run inside the
/// sandbox. Best-effort: a failure here only means the sandbox does not get the storage-hygiene exemption (an
/// extra, harmless machine-store entry for a disposable path -- see [`FloorIdentity`]'s own doc on why that costs
/// nothing but tidiness), never a security regression.
///
/// **P2-AR-0096: no GC.** The P2-AR-0095 sweep existed to bound the store's growth against markers that could
/// otherwise remain VALID forever after a leak (the object-identity design's own residual). A creator-liveness
/// marker cannot do that -- the instant its creator dies, [`creator_is_alive`] fails for every future reader,
/// permanently, so a leaked marker decays to inert on its own with no sweep needed (the same accepted-LOW shape
/// as the stale `adoption-floors/` entries this delta also leaves in place, AR90-C7).
///
/// [`Sandbox::create`]: crate::scheduler::sandbox::Sandbox::create
pub(crate) fn record_sandbox_root(state_root: &Path, canonical_root: &Path) -> Result<()> {
    let p = sandbox_record_path(state_root, canonical_root);
    if let Some(d) = p.parent() {
        std::fs::create_dir_all(d)?;
    }
    let pid = std::process::id();
    let Some(start_time) = process_start_time(pid) else {
        return Ok(()); // cannot read our own start time -- no exemption to grant, nothing to record
    };
    crate::util::write_json(
        &p,
        &json!({
            "recorded_at": crate::util::now_iso(),
            "path": canonical_root.to_string_lossy(),
            "creator_pid": pid,
            "creator_start_time": start_time,
        }),
    )
}

/// Remove the record [`record_sandbox_root`] wrote, mirroring [`Sandbox`]'s own removal of the sandbox directory
/// itself on drop. Best-effort: a leaked marker is, at worst, one harmless file under the machine's own protected
/// state, decaying to inert (never merely stale-but-still-valid) the moment its own creating process exits, by
/// [`creator_is_alive`]'s own construction; it grants no exemption to anything but a live process that named this
/// exact path at creation.
///
/// [`Sandbox`]: crate::scheduler::sandbox::Sandbox
pub(crate) fn remove_sandbox_record(state_root: &Path, canonical_root: &Path) {
    let _ = std::fs::remove_file(sandbox_record_path(state_root, canonical_root));
}

/// This checkout's own canonical absolute path, as a string — the load-bearing half of [`floor_anchor_key`] and
/// the value [`FloorIdentityState::minted_for_path`] records. Falls back to the given (uncanonicalised) path only
/// if canonicalisation itself fails (a path that does not exist yet); every real caller's `root` exists.
fn canonicalize_or(root: &Path) -> PathBuf {
    std::fs::canonicalize(root).unwrap_or_else(|_| root.to_path_buf())
}
fn canonical_path_string(root: &Path) -> String {
    canonicalize_or(root).to_string_lossy().into_owned()
}

/// The absolute anchor path for `root` under the protected state root `state_root` — a new `adoption-floors`
/// subdirectory of the SAME protected root [`crate::t2`] already resolves its own machine binding key from
/// ([`crate::srr::state::resolve_state_root`]) — reused, not reinvented, and outside every project (ARCH-0003 §7).
/// `None` inside an OS-created health sandbox ([`is_health_sandbox_root`]) — checked against the CANONICALISED
/// path (P2-AR-0091/AR90-D1: `floor_anchor_key` below always canonicalises; this function used to check the raw
/// `root` instead, an inconsistency the AR90 review flagged as unreachable only because `Project::open`
/// canonicalises `--root` first — closed here defensively rather than left to that one caller). Takes `state_root`
/// explicitly (never re-resolved from the calling process's own ambient environment here) so
/// [`adoption_floor_anchor_path_at`] can give the certification suite the exact path a `gov` subprocess run with a
/// DIFFERENT, per-scenario `XDG_STATE_HOME` would itself resolve, without either process mutating shared global
/// environment state.
fn anchor_path_under(state_root: &Path, root: &Path) -> Option<PathBuf> {
    if is_health_sandbox_root(state_root, &canonicalize_or(root)) {
        return None;
    }
    Some(
        state_root
            .join("adoption-floors")
            .join(floor_anchor_key(root))
            .join("identity.json"),
    )
}

